<script setup>
import { Bike, FileCheck2 } from '@lucide/vue';
import { onMounted, ref } from 'vue';
import AppButton from '../../components/ui/AppButton.vue';import StatusPill from '../../components/ui/StatusPill.vue';import { api,getApiError } from '../../services/api.js';import { useUiStore } from '../../stores/ui.js';
const drivers=ref([]),filter=ref('pending'),loading=ref(true);const ui=useUiStore();
async function load(){loading.value=true;try{const response=await api.get('/admin/drivers',{params:{approvalStatus:filter.value||undefined}});drivers.value=response.data.data}finally{loading.value=false}}onMounted(load);
async function decide(driver,status){if(!window.confirm(`${status==='approved'?'Approve':'Reject'} this driver application?`))return;try{await api.patch(`/admin/drivers/${driver._id}/approval`,{status});ui.notify(`Driver ${status}.`,'success');load()}catch(error){ui.notify(getApiError(error).message,'error')}}
</script>
<template><section class="page admin-page"><div class="page-header"><div><span class="eyebrow">Safety review</span><h1 class="page-title">Driver management</h1><p class="muted">Approve only drivers with complete, verified vehicle information.</p></div></div><div class="tabs"><button v-for="item in ['','pending','approved','rejected']" :key="item" :class="{active:filter===item}" @click="filter=item;load()">{{ item||'All' }}</button></div><div v-if="loading" class="skeleton" style="height:300px"></div><div v-else-if="!drivers.length" class="card empty-state"><div><FileCheck2 :size="38" /><p>No driver applications in this category.</p></div></div><div v-else class="driver-grid"><article v-for="driver in drivers" :key="driver._id" class="driver-card card"><div class="driver-top"><span><Bike :size="23" /></span><div><strong>{{ driver.userId?.firstName }} {{ driver.userId?.lastName }}</strong><small>{{ driver.userId?.email || driver.userId?.phone }}</small></div><StatusPill :status="driver.approvalStatus" /></div><div class="vehicle"><span>Vehicle</span><strong>{{ driver.vehicleId ? `${driver.vehicleId.bodyNumber} · ${driver.vehicleId.plateNumber}` : 'Not registered' }}</strong><span>Capacity</span><strong>{{ driver.vehicleId?.maximumPassengerCapacity ?? '—' }} passengers</strong></div><div v-if="driver.approvalStatus==='pending'" class="actions"><AppButton variant="danger" size="sm" @click="decide(driver,'rejected')">Reject</AppButton><AppButton size="sm" :disabled="!driver.vehicleId" @click="decide(driver,'approved')">Approve</AppButton></div></article></div></section></template>
<style scoped>.admin-page{max-width:1200px}.tabs{display:flex;gap:8px;overflow-x:auto;margin-bottom:16px}.tabs button{padding:9px 14px;border:1px solid var(--color-border);border-radius:999px;background:white;color:var(--color-text-soft);font-size:.72rem;font-weight:750;text-transform:capitalize}.tabs .active{border-color:var(--color-primary);background:#ecfdf5;color:var(--color-primary-dark)}.driver-grid{display:grid;gap:13px}.driver-card{display:grid;gap:15px;padding:16px}.driver-top{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:11px}.driver-top>span{display:grid;width:44px;height:44px;place-items:center;border-radius:14px;background:#d1fae5;color:var(--color-primary-dark)}.driver-top>div{display:grid;gap:3px}.driver-top strong{font-size:.83rem}.driver-top small{color:var(--color-text-soft);font-size:.67rem}.vehicle{display:grid;grid-template-columns:1fr auto;gap:8px;padding:12px;border-radius:11px;background:#f8fafc;font-size:.72rem}.vehicle span{color:var(--color-text-soft)}.actions{display:flex;justify-content:flex-end;gap:8px}@media(min-width:720px){.driver-grid{grid-template-columns:repeat(2,1fr)}}@media(min-width:1150px){.driver-grid{grid-template-columns:repeat(3,1fr)}}</style>

